(() => {
  const $=s=>document.querySelector(s),core=BookmarkCore,cacheKey='william-bookmark-library-v1',isLocal=location.hostname==='127.0.0.1';
  let items=[],folder='',paths=[],shown=60,tree={roots:[],nodes:[]},generation=0,active=0;
  const expanded=new Set(),cache=new Map(),queue=[];
  const shotControllers=new Set(),shotCache=new Map();let shotRun=0;
  function applyShot(visual,b,url){const image=document.createElement('img');image.alt=`${b.title}的真实网页快照`;image.src=url;image.decoding='async';const label=document.createElement('span');label.className='visual-label';label.textContent='网页快照';visual.dataset.snapshotReady='true';visual.replaceChildren(image,label);}
  function visualFor(b){return [...document.querySelectorAll('.bookmark-visual')].find(v=>v.dataset.id===b.id);}
  async function shotRequest(b,extra,run){const controller=new AbortController();shotControllers.add(controller);const timer=setTimeout(()=>controller.abort(),26000);try{return await fetch('/api/snapshot',{method:'POST',headers:{'X-William-Local':'1','Content-Type':'application/json'},body:JSON.stringify({url:b.url,profile:$('#edge-profile').value,...extra}),signal:controller.signal,cache:'no-store'});}finally{clearTimeout(timer);shotControllers.delete(controller);}}
  async function showCached(b,run,replace=false){const visual=visualFor(b);if(!visual||run!==shotRun)return;if(!replace&&shotCache.get(b.url)){applyShot(visual,b,shotCache.get(b.url));return;}try{const response=await shotRequest(b,{cacheOnly:true},run);if(!response.ok||run!==shotRun)return;const blob=await response.blob();if(run!==shotRun)return;const url=URL.createObjectURL(blob),old=shotCache.get(b.url);shotCache.set(b.url,url);if(old)URL.revokeObjectURL(old);if(shotCache.size>60){const [key,value]=shotCache.entries().next().value;shotCache.delete(key);URL.revokeObjectURL(value);}const current=visualFor(b);if(current)applyShot(current,b,url);}catch{/* Keep the last displayed image. */}}
  function stopShots(){shotRun++;for(const controller of shotControllers)controller.abort();}
  async function scheduleShots(result){const run=shotRun,status=$('#snapshot-progress');if(!isLocal||!$('#edge-profile').value)return;status.textContent='正在读取已保存的快照';const visible=result.slice(0,shown);let index=0;async function hydrate(){while(index<visible.length&&run===shotRun)await showCached(visible[index++],run);}const planRequest=api('/api/snapshot-plan?profile='+encodeURIComponent($('#edge-profile').value));let plan;try{[plan]=await Promise.all([planRequest,hydrate(),hydrate(),hydrate()]);}catch{if(run===shotRun)status.textContent='缓存状态读取失败，暂不重新截图';return;}if(run!==shotRun)return;const seen=new Set(),ordered=result.filter(b=>{if(seen.has(b.url))return false;seen.add(b.url);return true;}),jobs=ordered.filter(b=>!plan.states[b.url]?.fresh),reused=ordered.length-jobs.length;if(!jobs.length){status.textContent=`已复用缓存快照 · ${reused} 个`;return;}if(!$('#real-snapshots').checked){status.textContent=`已复用 ${reused} 个缓存 · ${jobs.length} 个待截图（已暂停）`;return;}const old=jobs.filter(b=>plan.states[b.url]?.exists).length;status.textContent=`待生成 ${jobs.length-old} 个 · 待更新 ${old} 个 · 已缓存 ${reused} 个`;let succeeded=0,failed=0;for(let i=0;i<jobs.length&&run===shotRun;i++){const b=jobs[i];status.textContent=`快照生成进度 ${i+1} / ${jobs.length} · 已复用 ${reused} 个缓存`;try{const response=await shotRequest(b,{returnInfo:true},run);if(run!==shotRun)return;if(response.ok){const info=await response.json();if(info.stale)failed++;else succeeded++;await showCached(b,run,!info.cached);}else failed++;}catch{failed++;}if(run!==shotRun)return;}if(run===shotRun)status.textContent=`已复用 ${reused} 个缓存 · 新完成 ${succeeded} 个${failed?` · ${failed} 个未成功（保留旧图或封面）`:''}`;}
  const observer=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){observer.unobserve(e.target);enqueue(e.target);}},{rootMargin:'120px'}):null;
  const message=text=>$('#library-status').textContent=text;
  function theme(name){const value=['sage','ember','crimson','sky'].includes(name)?name:'ember';document.documentElement.dataset.theme=value;document.querySelectorAll('[data-palette]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.palette===value)));try{localStorage.setItem('william-palette',value);}catch{}}
  try{theme(localStorage.getItem('william-palette'));}catch{theme('ember');}document.querySelectorAll('[data-palette]').forEach(b=>b.addEventListener('click',()=>theme(b.dataset.palette)));
  function save(){try{if($('#remember-bookmarks').checked)localStorage.setItem(cacheKey,JSON.stringify({items,folders:paths}));else localStorage.removeItem(cacheKey);}catch{message('收藏已载入，但浏览器存储空间不足。');}}
  function choose(key){folder=key;shown=60;const selected=tree.nodes.find(n=>n.key===key);if(selected)for(let d=1;d<selected.path.length;d++)expanded.add(JSON.stringify(selected.path.slice(0,d)));renderTree();render();}
  function renderTree(){const list=document.createElement('ul');list.className='folder-tree';function branch(nodes,parent){for(const n of nodes){const li=document.createElement('li'),row=document.createElement('div'),toggle=document.createElement('button'),button=document.createElement('button');row.className='folder-row';toggle.className='folder-toggle';toggle.textContent=n.children.length?(expanded.has(n.key)?'▾':'▸'):'·';toggle.disabled=!n.children.length;toggle.setAttribute('aria-label',`${expanded.has(n.key)?'收起':'展开'} ${n.name}`);toggle.setAttribute('aria-expanded',String(expanded.has(n.key)));button.className='folder-button';button.classList.toggle('selected',folder===n.key);button.title=n.path.join(' / ')||'未分类';button.setAttribute('aria-pressed',String(folder===n.key));const name=document.createElement('span'),count=document.createElement('span');name.textContent=n.name;count.textContent=n.count;button.append(name,count);button.addEventListener('click',()=>choose(n.key));row.append(toggle,button);li.append(row);if(n.children.length){const children=document.createElement('ul');children.hidden=!expanded.has(n.key);branch(n.children,children);li.append(children);toggle.addEventListener('click',()=>{expanded.has(n.key)?expanded.delete(n.key):expanded.add(n.key);renderTree();});}parent.append(li);}}branch(tree.roots,list);$('#folder-list').replaceChildren(list);}
  function load(data,label,folders=[]){for(const url of shotCache.values())if(url)URL.revokeObjectURL(url);shotCache.clear();items=core.normalize(data);paths=folders;folder='';shown=60;expanded.clear();cache.clear();tree=core.folderTree(items,paths);for(const n of tree.roots)expanded.add(n.key);renderTree();$('#folder-filter').replaceChildren(new Option('全部收藏夹',''),...tree.nodes.map(n=>new Option(`${n.path.join(' / ')||n.name} (${n.count})`,n.key)));$('#domain-filter').replaceChildren(new Option('全部站点',''),...[...new Set(items.map(b=>core.siteKey(b.url)))].sort().map(d=>new Option(d,d)));$('#total-count').textContent=items.length;$('#all-count').textContent=items.length;$('#source-label').textContent=label;$('#sync-time').textContent=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});$('.source-bar').classList.toggle('connected',items.length>0);render();save();}
  function filtered(unique=true){return core.select(items,{query:$('#bookmark-search').value,folder,domain:$('#domain-filter').value,sort:$('#sort-filter').value,uniqueSites:unique&&$('#unique-sites').checked});}
  function fallback(visual,b,data={}){const page=document.createElement('div');page.className='page-fallback';const domain=document.createElement('span'),heading=document.createElement('strong'),desc=document.createElement('p'),badge=document.createElement('span');domain.className='fallback-domain';domain.textContent=core.siteKey(b.url);heading.textContent=data.title||b.title;desc.textContent=data.description||data.text?.slice(0,180)||b.description||'已收藏的网页 · 点击直接访问';badge.className='visual-label';badge.textContent=data.description||data.text?'内容摘要':'站点入口';page.append(domain,heading,desc);visual.replaceChildren(page,badge);}
  function paint(visual,b,data){if(visual.dataset.snapshotReady)return;fallback(visual,b,data);if(!data.image)return;const image=document.createElement('img');image.alt=data.imageAlt||`${b.title}的网页封面`;image.referrerPolicy='no-referrer';image.decoding='async';image.addEventListener('load',()=>{if(visual.dataset.snapshotReady||!visual.isConnected||image.naturalWidth<80||image.naturalHeight<40)return;const label=document.createElement('span');label.className='visual-label';label.textContent='网页封面';visual.replaceChildren(image,label);});image.src=data.image;}
  function enqueue(visual){const b=items.find(item=>item.id===visual.dataset.id);if(!b)return;if(cache.has(b.url)){paint(visual,b,cache.get(b.url));return;}if(!isLocal||!$('#edge-profile').value)return;queue.push({visual,b,generation});pump();}
  async function pump(){while(active<3&&queue.length){const task=queue.shift();if(task.generation!==generation||!task.visual.isConnected)continue;active++;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const data=cache.get(task.b.url)||await api('/api/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:task.b.url,profile:$('#edge-profile').value}),signal:controller.signal});if(task.generation===generation){cache.set(task.b.url,data);if(task.visual.isConnected)paint(task.visual,task.b,data);}}catch{if(task.generation===generation)cache.set(task.b.url,{});}finally{clearTimeout(timeout);active--;pump();}}}
  function card(b){const link=document.createElement('a');link.className='bookmark-card';link.href=b.url;link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label',`打开 ${b.title}`);const top=document.createElement('div'),icon=document.createElement('span'),domain=document.createElement('span'),title=document.createElement('h3'),visual=document.createElement('div'),crumb=document.createElement('p'),open=document.createElement('span');top.className='bookmark-top';icon.className='bookmark-icon';icon.setAttribute('aria-hidden','true');icon.textContent=core.siteKey(b.url)[0].toUpperCase();domain.className='bookmark-domain';domain.textContent=core.siteKey(b.url);top.append(icon,domain);title.className='bookmark-title';title.textContent=b.title;title.title=b.title;visual.className='bookmark-visual';visual.dataset.id=b.id;fallback(visual,b);crumb.className='bookmark-folder';crumb.textContent=b.folder.join(' / ')||'未分类';open.className='card-open';open.textContent='直接访问 ↗';link.append(top,title,visual,crumb,open);return link;}
  function render(){generation++;stopShots();observer?.disconnect();queue.length=0;const result=filtered(),raw=filtered(false);$('#current-folder').textContent=tree.nodes.find(n=>n.key===folder)?.path.join(' / ')||(folder?'未分类':'全部收藏');$('#result-count').textContent=`${result.length} 个入口${$('#unique-sites').checked?` · 合并 ${raw.length-result.length} 个同站页面`:` / ${items.length}`}`;$('#bookmark-results').replaceChildren(...result.slice(0,shown).map(card));for(const visual of document.querySelectorAll('.bookmark-visual')){observer?observer.observe(visual):enqueue(visual);}scheduleShots(result);$('#library-empty').hidden=result.length>0;$('#library-empty h3').textContent=items.length?'这个收藏夹下没有匹配的网页。':'让收藏重新被看见。';$('#library-empty p').textContent=items.length?'换一个收藏夹或关键词，或重置筛选。':'读取本机 Edge 收藏夹，或导入收藏文件。';$('#load-more').hidden=result.length<=shown;$('#load-more').textContent=`显示更多（还有 ${Math.max(0,result.length-shown)} 个）`;$('#all-folders').classList.toggle('selected',!folder);$('#folder-filter').value=folder;}
  async function api(url,options={}){const response=await fetch(url,{...options,headers:{'X-William-Local':'1',...(options.headers||{})},cache:'no-store'});let data;try{data=await response.json();}catch{throw new Error('本机读取工具尚未连接，请启动本机工具，或导入收藏文件。');}if(!response.ok)throw new Error(data.error||'读取失败');return data;}
  async function read(){if(!isLocal){message('本机版支持直接读取和自动显示封面，当前页面可导入收藏文件。');return;}$('#read-edge').disabled=true;message('正在读取 Edge 收藏夹…');try{const available=await api('/api/bookmarks/profiles');if(!available.profiles.length)throw new Error('未找到 Edge 收藏夹');const selected=$('#edge-profile').value;$('#edge-profile').replaceChildren(...available.profiles.map(p=>new Option(p.name,p.id)));if(available.profiles.some(p=>p.id===selected))$('#edge-profile').value=selected;$('#edge-profile').hidden=available.profiles.length<=1;const data=await api('/api/bookmarks?profile='+encodeURIComponent($('#edge-profile').value));load(data.bookmarks,'Edge 收藏夹 · '+$('#edge-profile').selectedOptions[0].textContent,data.folders||[]);message(`已读取 ${items.length} 个收藏。点击目录或收藏夹筛选，点击卡片直接访问。`);}catch(error){message(error.message);}finally{$('#read-edge').disabled=false;}}
  $('#read-edge').addEventListener('click',read);$('#edge-profile').addEventListener('change',read);$('#import-bookmarks').addEventListener('click',()=>$('#bookmark-file').click());
  $('#bookmark-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw new Error('文件超过 10 MB');const text=await file.text();let data,folders=[];if(/^\s*[\[{]/.test(text)){const json=JSON.parse(text);data=json.roots?core.fromEdge(json):core.normalize(Array.isArray(json)?json:json.bookmarks||json.items);folders=json.roots?core.edgeFolders(json):json.folders||[];}else{data=core.fromHtml(text);folders=core.htmlFolders(text);}if(!data.length&&!folders.length)throw new Error('没有找到收藏夹数据');load(data,'已导入 · '+file.name,folders);message(`已导入 ${items.length} 个入口，点击卡片直接访问。`);}catch(error){message(error.message||'请导入 Edge 收藏夹文件。');}e.target.value='';});
  $('#clear-bookmarks').addEventListener('click',()=>{$('#remember-bookmarks').checked=false;load([],'还没有载入收藏');$('#sync-time').textContent='';reset();message('已清空本页副本，Edge 原收藏未改动。');});$('#remember-bookmarks').addEventListener('change',save);
  function reset(){folder='';$('#bookmark-search').value='';$('#domain-filter').value='';$('#sort-filter').value='source';$('#unique-sites').checked=false;shown=60;renderTree();render();}
  $('#reset-filters').addEventListener('click',reset);$('#all-folders').addEventListener('click',()=>choose(''));$('#folder-filter').addEventListener('change',e=>choose(e.target.value));for(const id of ['bookmark-search','domain-filter','sort-filter','unique-sites'])$('#'+id).addEventListener(id==='bookmark-search'?'input':'change',()=>{shown=60;render();});$('#load-more').addEventListener('click',()=>{shown+=60;render();});
  for(const view of ['grid','list'])$('#'+view+'-view').addEventListener('click',()=>{$('#bookmark-results').classList.toggle('list-view',view==='list');for(const other of ['grid','list'])$('#'+other+'-view').setAttribute('aria-pressed',String(other===view));});document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#bookmark-search').focus();}});
  try{const cached=JSON.parse(localStorage.getItem(cacheKey)||'null');if(cached?.items){$('#remember-bookmarks').checked=true;load(cached.items,'此浏览器保存的收藏',cached.folders||[]);}}catch{message('请重新载入收藏。');}$('#real-snapshots').addEventListener('change',()=>{stopShots();$('#snapshot-progress').textContent=$('#real-snapshots').checked?'准备按顺序处理快照':'已暂停截图，旧截图保留';scheduleShots(filtered());});addEventListener('pagehide',()=>{stopShots();for(const url of shotCache.values())if(url)URL.revokeObjectURL(url);shotCache.clear();});render();if(isLocal)read();else message('导入收藏文件即可使用；自动读取网页封面请使用本机版。');
})();
